draw:
var padL = 36, padR = 16, padT = 26, padB = 34;
var yMid = (H - padB + padT) / 2;
var A = (H - padT - padB) * 0.32;
var Lx = W - padL - padR;
var lam = Lx / 2.2;            // two-ish wavelengths across the picture
var k = 2 * Math.PI / lam;

ctx.lineWidth = 1;
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(padL, yMid); ctx.lineTo(W - padR, yMid); ctx.stroke();

ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
for (var i = 0; i <= 300; i++) {
  var x = padL + Lx * i / 300;
  var y = yMid - A * Math.sin(k * (x - padL));
  if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
}
ctx.stroke();

var crest1 = padL + lam * 0.25;
var crest2 = padL + lam * 1.25;
var trough = padL + lam * 0.75;

// wavelength bar between the two crests
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.2;
var bar = padT - 8;
ctx.beginPath(); ctx.moveTo(crest1, bar); ctx.lineTo(crest2, bar); ctx.stroke();
ctx.beginPath(); ctx.moveTo(crest1, bar); ctx.lineTo(crest1 + 6, bar - 4); ctx.lineTo(crest1 + 6, bar + 4); ctx.closePath();
ctx.fillStyle = C.figure; ctx.fill();
ctx.beginPath(); ctx.moveTo(crest2, bar); ctx.lineTo(crest2 - 6, bar - 4); ctx.lineTo(crest2 - 6, bar + 4); ctx.closePath();
ctx.fill();
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(crest1, bar); ctx.lineTo(crest1, yMid - A); ctx.stroke();
ctx.beginPath(); ctx.moveTo(crest2, bar); ctx.lineTo(crest2, yMid - A); ctx.stroke();
ctx.setLineDash([]);

// amplitude bar at the trough
ctx.strokeStyle = C.figure;
ctx.beginPath(); ctx.moveTo(trough, yMid); ctx.lineTo(trough, yMid + A); ctx.stroke();
ctx.beginPath(); ctx.moveTo(trough, yMid + A); ctx.lineTo(trough - 4, yMid + A - 6); ctx.lineTo(trough + 4, yMid + A - 6); ctx.closePath();
ctx.fillStyle = C.figure; ctx.fill();

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

ctx.fillStyle = C.ink;
ctx.fillText("one wavelength, lambda", (crest1 + crest2) / 2 - 52, bar - 8);
ctx.fillText("amplitude A", trough + 8, yMid + A * 0.6);
ctx.fillText("crest", crest1 - 14, yMid - A - 8);
ctx.fillText("trough", trough + 8, yMid + A + 14);
ctx.fillText("y = 0 line (rope at rest)", padL + 4, yMid - 6);
ctx.fillText("distance x along the rope", W / 2 - 68, H - 8);
ctx.fillText("y", 10, yMid - A - 6);

ctx.strokeStyle = C.ink;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(padL, yMid - A - 16); ctx.lineTo(padL + 30, yMid - A - 16); ctx.stroke();
ctx.beginPath(); ctx.moveTo(padL + 30, yMid - A - 16); ctx.lineTo(padL + 24, yMid - A - 20); ctx.lineTo(padL + 24, yMid - A - 12);
ctx.closePath(); ctx.fillStyle = C.ink; ctx.fill();
ctx.fillText("v", padL + 34, yMid - A - 12);

var A = p.amp / 100.0;          // metres
var lam = p.lam;                // metres
var f = p.freq;                 // Hz
var k = 2 * Math.PI / lam;
var w = 2 * Math.PI * f;
var v = f * lam;

var padL = 34, padR = 14, padT = 18, padB = 26;
var Lx = 2.0;                                  // metres of rope shown
var sx = (W - padL - padR) / Lx;
var yMid = (H - padB + padT) / 2;
var sy = (H - padT - padB) / 2 / 0.055;        // metres -> px, fixed scale
var X = function (x) { return padL + x * sx; };
var Y = function (y) { return yMid - y * sy; };

ctx.lineWidth = 1;
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(padL, Y(0)); ctx.lineTo(W - padR, Y(0)); ctx.stroke();

// the rope
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
for (var i = 0; i <= 240; i++) {
  var x = Lx * i / 240;
  var y = A * Math.sin(k * x - w * t);
  if (i === 0) ctx.moveTo(X(x), Y(y)); else ctx.lineTo(X(x), Y(y));
}
ctx.stroke();

// one marked element, moving only up and down
var xm = 0.45 * Lx;
var ym = A * Math.sin(k * xm - w * t);
var vy = -w * A * Math.cos(k * xm - w * t);
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(X(xm), Y(A * 1.25)); ctx.lineTo(X(xm), Y(-A * 1.25)); ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(X(xm), Y(ym), 5, 0, Math.PI * 2); ctx.fill();

// velocity arrow on that element
var arrow = vy * sy * 0.25;
if (Math.abs(arrow) > 3) {
  ctx.strokeStyle = C.figure;
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(X(xm), Y(ym));
  ctx.lineTo(X(xm), Y(ym) - arrow);
  ctx.stroke();
  var s = arrow > 0 ? 1 : -1;
  ctx.beginPath();
  ctx.moveTo(X(xm), Y(ym) - arrow);
  ctx.lineTo(X(xm) - 4, Y(ym) - arrow + 6 * s);
  ctx.lineTo(X(xm) + 4, Y(ym) - arrow + 6 * s);
  ctx.closePath(); ctx.fillStyle = C.figure; ctx.fill();
}

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

ctx.fillStyle = C.ink;
ctx.fillText("rope element", X(xm) + 8, padT + 10);
ctx.fillText("wave travels this way", padL + 4, H - 8);
ctx.strokeStyle = C.ink;
ctx.lineWidth = 1.2;
var ax = padL + 150, ay = H - 12;
ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(ax + 26, ay); ctx.stroke();
ctx.beginPath(); ctx.moveTo(ax + 26, ay); ctx.lineTo(ax + 20, ay - 4); ctx.lineTo(ax + 20, ay + 4);
ctx.closePath(); ctx.fillStyle = C.ink; ctx.fill();
ctx.fillText("y", 8, Y(0) - 6);
ctx.fillText("x", W - padR - 8, Y(0) + 16);

out.note = "v = f x lambda = " + v.toFixed(2) + " m/s, period T = " + (1 / f).toFixed(3)
  + " s, max transverse speed " + (w * A).toFixed(2) + " m/s";

var T = p.tension, mu = p.mu / 1000.0;   // slider in g/m
var v = Math.sqrt(T / mu);
var L = 6.0;                              // metres of rope
var tt = L / v;                           // transit time

var padL = 30, padR = 20;
var yMid = H * 0.52;
var sx = (W - padL - padR) / L;

// rope at rest
ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(padL, yMid); ctx.lineTo(W - padR, yMid); ctx.stroke();

// a gaussian pulse marching right, restarting after it leaves
var cycle = tt + 0.5;
var now = t % cycle;
var xc = v * now;
var width = 0.45;
var amp = H * 0.24;

ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
for (var i = 0; i <= 300; i++) {
  var x = L * i / 300;
  var u = (x - xc) / width;
  var y = yMid - amp * Math.exp(-u * u);
  if (i === 0) ctx.moveTo(padL + x * sx, y); else ctx.lineTo(padL + x * sx, y);
}
ctx.stroke();

// walls
ctx.strokeStyle = C.rule;
ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(padL, yMid - amp * 1.5); ctx.lineTo(padL, yMid + amp * 0.8); ctx.stroke();
ctx.beginPath(); ctx.moveTo(W - padR, yMid - amp * 1.5); ctx.lineTo(W - padR, yMid + amp * 0.8); ctx.stroke();

// clock bar
var frac = Math.min(now / tt, 1);
ctx.strokeStyle = C.figure;
ctx.lineWidth = 4;
ctx.beginPath();
ctx.moveTo(padL, H - 14);
ctx.lineTo(padL + frac * (W - padL - padR), H - 14);
ctx.stroke();

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

ctx.fillStyle = C.ink;
ctx.fillText("6.0 m of rope, tension T pulling both ends", padL + 6, 16);
ctx.fillText("elapsed " + Math.min(now, tt).toFixed(3) + " s of " + tt.toFixed(3) + " s", padL + 6, H - 20);

out.note = "v = sqrt(T/mu) = sqrt(" + T.toFixed(0) + " / " + mu.toFixed(4) + ") = "
  + v.toFixed(1) + " m/s, so the pulse crosses 6.0 m in " + tt.toFixed(3) + " s";

var P = p.power, r0 = p.dist;
var I0 = 1e-12;
var I = P / (4 * Math.PI * r0 * r0);
var db = 10 * Math.log10(I / I0);

var padL = 44, padR = 16, padT = 18, padB = 30;
var rMin = 1, rMax = 400;
var lx = function (r) {
  return padL + (W - padL - padR) * (Math.log10(r) - Math.log10(rMin)) / (Math.log10(rMax) - Math.log10(rMin));
};
var dbMin = 20, dbMax = 130;
var ly = function (d) {
  return H - padB - (H - padT - padB) * (d - dbMin) / (dbMax - dbMin);
};

// axes
ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(padL, padT); ctx.lineTo(padL, H - padB); ctx.lineTo(W - padR, H - padB); ctx.stroke();

// gridline every 20 dB
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

ctx.fillStyle = C.ink;
for (var d = dbMin; d <= dbMax; d += 20) {
  ctx.strokeStyle = C.faint;
  ctx.beginPath(); ctx.moveTo(padL, ly(d)); ctx.lineTo(W - padR, ly(d)); ctx.stroke();
  ctx.fillText(d + " dB", 4, ly(d) + 4);
}
var marks = [1, 10, 100];
for (var j = 0; j < marks.length; j++) {
  ctx.strokeStyle = C.faint;
  ctx.beginPath(); ctx.moveTo(lx(marks[j]), padT); ctx.lineTo(lx(marks[j]), H - padB); ctx.stroke();
  ctx.fillStyle = C.ink;
  ctx.fillText(marks[j] + " m", lx(marks[j]) - 10, H - padB + 14);
}

// the curve
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
for (var i = 0; i <= 200; i++) {
  var r = Math.pow(10, Math.log10(rMin) + (Math.log10(rMax) - Math.log10(rMin)) * i / 200);
  var y = 10 * Math.log10(P / (4 * Math.PI * r * r) / I0);
  var yy = Math.max(Math.min(y, dbMax), dbMin);
  if (i === 0) ctx.moveTo(lx(r), ly(yy)); else ctx.lineTo(lx(r), ly(yy));
}
ctx.stroke();

// marker
var dbc = Math.max(Math.min(db, dbMax), dbMin);
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(lx(r0), H - padB); ctx.lineTo(lx(r0), ly(dbc)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(padL, ly(dbc)); ctx.lineTo(lx(r0), ly(dbc)); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(lx(r0), ly(dbc), 5, 0, Math.PI * 2); ctx.fill();

ctx.fillStyle = C.ink;
ctx.fillText("sound level against distance, log scale", padL + 8, padT + 12);
ctx.fillText("every doubling of distance costs 6 dB", padL + 8, padT + 28);

out.note = "at " + r0.toFixed(1) + " m: I = " + I.toExponential(2) + " W/m^2, level = " + db.toFixed(1) + " dB";
